def _project(points, cam_pos, cam_R, fovy_deg, aspect):
    """Projects world points into a MuJoCo camera's image.

    The camera looks along its -z axis with +y up and +x to the right.

    Args:
        points (numpy.ndarray): World positions, shape (N, 3), in metres.
        cam_pos (numpy.ndarray): World position of the camera, 3 values in metres.
        cam_R (numpy.ndarray): Camera orientation, 3x3 matrix whose columns are the camera axes in the world frame.
        fovy_deg (float): Vertical field of view (FOV) of the camera in degrees.
        aspect (float): Image width divided by image height.

    Returns:
        tuple: (u, v, depth), each a numpy.ndarray of N values. u and v are normalized device coordinates (NDC), within [-1, 1] for
        points inside the image (u to the right, v up); depth is the distance in metres along the optical axis (negative or
        small for points behind or beside the camera, for which u and v are not meaningful).
    """
    pc = (points - cam_pos) @ cam_R                       # = R^T (p - pos), rows are points
    depth = -pc[:, 2]
    th = np.tan(np.radians(fovy_deg) / 2)
    safe = np.maximum(depth, 1e-6)
    return pc[:, 0] / safe / (th * aspect), pc[:, 1] / safe / th, depth


def _points_array(points):
    """Converts the points argument of frame_points to names and an array.

    Args:
        points (dict or array-like): {name: (x, y, z)} or a sequence of (x, y, z).

    Returns:
        tuple: (names, array), where names is a list of str (the dict keys, or "p0", "p1", ... for a sequence) and array is a
        float numpy.ndarray of shape (N, 3).
    """
    if isinstance(points, dict):
        names = list(points)
        return names, np.array([points[n] for n in names], float)
    arr = np.asarray(points, float)
    return [f"p{i}" for i in range(len(arr))], arr


class _Scratch:
    """Kinematics workspace for the framing search: a private MjData plus the neck, camera and collision geom bookkeeping.

    Attributes:
        model (mujoco.MjModel): The model.
        cfg (dict): The framing configuration (FRAMING_CFG with the caller's changes).
        d (mujoco.MjData): Scratch data, with qpos copied from the caller's data at construction; the caller's data is never touched.
        ids (dict): The neck_ids dictionary of the model.
        cam (int): Id of the camera named cfg["camera"].
        res (numpy.ndarray): Resolution (width, height) of that camera, in pixels.
        aspect (float): Width divided by height of that camera.
        fovy (float): Vertical field of view of that camera, in degrees.
        root (int): Id of the neck's base body.
        neck_geoms (list of int): Ids of the collidable geoms on the neck.
        other_geoms (list of int): Ids of the collidable geoms that are neither on the neck nor on the world body.
        posture (numpy.ndarray): The posture pose of the cost (joint angles, radians).
    """

    def __init__(self, model, data, cfg, neck_specs):
        """Builds the workspace.

        Args:
            model (mujoco.MjModel): A model with the neck and the camera cfg["camera"].
            data (mujoco.MjData): Data whose qpos is the starting configuration of everything but the neck.
            cfg (dict): The framing configuration; "camera" and "posture_pose" are used here.
            neck_specs (dict): Neck specification (robot_specs.NECK_SPECS).

        Raises:
            ValueError: If the model has no neck.
        """
        self.model, self.cfg = model, cfg
        self.d = mujoco.MjData(model)
        self.d.qpos[:] = data.qpos
        self.ids = neck_ids(model, neck_specs)
        if self.ids is None:
            raise ValueError("the model has no neck")
        self.posture = np.array(neck_specs["drive_pose"] if cfg.get("posture_pose") is None else cfg["posture_pose"], float)
        self.cam = model.camera(cfg["camera"]).id
        self.res = model.cam_resolution[self.cam]
        self.aspect = float(self.res[0]) / float(self.res[1])
        self.fovy = float(model.cam_fovy[self.cam])
        root = model.body(neck_specs["prefix"] + "base").id
        in_neck = lambda b: any(a == root for a in self._ancestors(b))
        self.neck_geoms = [g for g in range(model.ngeom) if in_neck(int(model.geom_bodyid[g])) and (model.geom_contype[g] or model.geom_conaffinity[g])]
        self.other_geoms = [g for g in range(model.ngeom) if not in_neck(int(model.geom_bodyid[g])) and int(model.geom_bodyid[g]) != 0
                            and (model.geom_contype[g] or model.geom_conaffinity[g])]
        self.root = root

    def _ancestors(self, b):
        """Yields a body id and then the ids of its parent bodies, up to but not including the world body.

        Args:
            b (int): Body id to start from.

        Yields:
            int: `b`, then its parent, and so on.
        """
        while b > 0:
            yield b
            b = int(self.model.body_parentid[b])

    def pose(self, q):
        """Computes the camera pose for a neck configuration, in the scratch data.

        Args:
            q (sequence of float): Neck joint angles in radians, in the order of the active joints.

        Returns:
            tuple: (pos, R) with pos (numpy.ndarray, 3 values) the world position of the camera in metres and R (numpy.ndarray,
            3x3) its orientation, as copies.
        """
        d = self.d
        for a, v in zip(self.ids["qadr"], q):
            d.qpos[a] = v
        mujoco.mj_kinematics(self.model, d)
        mujoco.mj_camlight(self.model, d)
        return d.cam_xpos[self.cam].copy(), d.cam_xmat[self.cam].reshape(3, 3).copy()

    def contacts(self, q):
        """Finds the neck geoms closer than contact_margin to anything that is not the neck.

        Only the other geoms within 1.5 m of the neck base are tested.

        Args:
            q (sequence of float): Neck joint angles in radians, in the order of the active joints.

        Returns:
            list: One (neck_name, other_body_name) tuple of str per close pair, where neck_name is the neck geom's name or, if it
            has none, its body's name, and other_body_name is the body of the other geom. Empty if nothing is close.
        """
        self.pose(q)
        d, m, ft, out = self.d, self.model, np.zeros(6), []
        base = d.xpos[self.root]
        near = [g for g in self.other_geoms if np.linalg.norm(d.geom_xpos[g] - base) < 1.5]
        for ng in self.neck_geoms:
            for og in near:
                if mujoco.mj_geomDistance(m, d, ng, og, self.cfg["contact_margin"], ft) < self.cfg["contact_margin"]:
                    out.append((m.geom(ng).name or m.body(m.geom_bodyid[ng]).name, m.body(m.geom_bodyid[og]).name))
        return out


def _evaluate(sc, q, pts, center, q0):
    """Scores a neck configuration: how badly the points miss the margin frame, how far off-aim, how far from the start pose.

    The cost is 100 * the largest violation + 10 * the summed violation + aim_weight * aim error^2 + move_weight * the squared
    distance of `q` from `q0` + posture_weight * the squared distance of `q` from the posture pose. The violation of a point is its largest |u| or |v| beyond 1 - 2 * margin (so a point that
    keeps the margin has none), or 10 if it is closer than near_depth to the camera.

    Args:
        sc (_Scratch): The workspace; its scratch data is changed.
        q (numpy.ndarray): Neck joint angles in radians.
        pts (numpy.ndarray): World points, shape (N, 3), in metres.
        center (numpy.ndarray): World point the camera should look at (the bounding box centre), 3 values in metres.
        q0 (numpy.ndarray): Reference neck joint angles in radians for the cost of moving.

    Returns:
        tuple: (cost, details). cost is a float. details is the tuple (pos, R, u, v, depth, aim): the camera's world position
        (3 values, metres) and orientation (3x3), the normalized image coordinates u and v and the depth in metres of
        each point (N values each), and the aim error in radians (the angle between the optical axis and the direction to `center`).
    """
    cfg = sc.cfg
    pos, R = sc.pose(q)
    u, v, depth = _project(pts, pos, R, sc.fovy, sc.aspect)
    limit = 1.0 - 2.0 * cfg["margin"]                      # |u|, |v| <= 0.8 keeps 10 % free on every side
    ext = np.maximum(np.abs(u), np.abs(v))
    viol = np.where(depth < cfg["near_depth"], 10.0, np.maximum(0.0, ext - limit))
    axis = -R[:, 2]
    to_c = center - pos
    aim = float(np.arccos(np.clip(axis @ to_c / max(np.linalg.norm(to_c), 1e-9), -1, 1)))
    cost = 100.0 * float(viol.max()) + 10.0 * float(viol.sum()) + cfg["aim_weight"] * aim ** 2 + cfg["move_weight"] * float(np.sum((q - q0) ** 2)) \
        + cfg["posture_weight"] * float(np.sum((q - sc.posture) ** 2))
    return cost, (pos, R, u, v, depth, aim)


def _polish_least_movement(sc, pts, q0, q_start, lo, hi, cfg):
    """The least-movement pose exactly: minimise |q - q0|^2 with every point at least `margin` inside the image (a hair more, 1e-4) and in front of the camera (SLSQP from a simplex result).

    Returns:
        numpy.ndarray or None: The joint angles, or None if the solver did not end at a feasible pose.
    """
    lim = 1.0 - 2.0 * cfg["margin"] - 1e-4

    def cons(q):
        pos, R = sc.pose(np.clip(q, lo, hi))
        u, v, depth = _project(pts, pos, R, sc.fovy, sc.aspect)
        return np.concatenate([lim - u, lim + u, lim - v, lim + v, depth - 2.0 * cfg["near_depth"]])

    r = minimize(lambda q: float(np.sum((q - q0) ** 2)), np.asarray(q_start, float), jac=lambda q: 2.0 * (q - q0), method="SLSQP", bounds=list(zip(lo, hi)),
                 constraints={"type": "ineq", "fun": cons}, options={"maxiter": 200, "ftol": 1e-14})
    q = np.clip(r.x, lo, hi)
    return q if float(cons(q).min()) >= -1e-9 else None


def frame_points(model, data, points, cfg=FRAMING_CFG, neck_specs=robot_specs.NECK_SPECS, start=None, local=False):
    """Finds the neck joint targets that frame world points in the neck camera's image.

    The search minimizes the cost of _evaluate. Unless `local`, it first scores a grid of cfg["coarse_steps"] values per active
    joint over the joint ranges and refines the best cfg["n_refine"] grid points; the start pose is always refined too (with move_weight 0 the
    start only adds one more candidate, so the answer does not depend on it). The
    refinement is the Nelder-Mead simplex method with at most cfg["refine_evals"] cost evaluations, within the joint limits.
    The candidates are then taken in order of cost and the first without a collision is returned; if all collide, the best one is
    returned with its contacts. The caller's `data` is not modified.

    Args:
        model (mujoco.MjModel): A model with the neck and the camera named cfg["camera"].
        data (mujoco.MjData): Current data; its qpos gives the pose of the robot and the current neck angles.
        points (dict or array-like): The world points to frame: {name: (x, y, z)} or a sequence of (x, y, z), in metres.
        cfg (dict): Framing configuration. Keys left out are taken from FRAMING_CFG: "camera" (name), "margin" (fraction of the
            image kept free on every side), "coarse_steps", "n_refine", "refine_evals", "contact_margin" (metres), "aim_weight"
            (per radian squared), "move_weight" (per radian squared), "posture_weight" (per radian squared), "posture_pose", "simplex_step"
            (radians) and "near_depth" (metres). Defaults to FRAMING_CFG.
        neck_specs (dict): Neck specification. Defaults to robot_specs.NECK_SPECS.
        start (sequence of float or None): Neck joint angles in radians, in the order of the active joints, from which the cost of
            moving is measured. Defaults to None, which means the current neck angles in `data`.
        local (bool): If True, skip the coarse search and refine only from `start`. Defaults to False.

    Returns:
        tuple: (targets, report). targets (dict) maps each active neck joint name (without prefix) to its target angle in radians
        (the same as report["neck_targets"]). report (dict) has the keys
            "fits" (bool): True if every point keeps at least cfg["margin"] to every image edge.
            "worst_margin" (float): Smallest margin to the nearest image edge of any point, as a fraction of the image dimension
                (-1 for a point closer than near_depth to the camera).
            "aim_error_deg" (float): Angle in degrees between the optical axis and the direction to the centre of the points.
            "camera_pos" (list of float): World position of the camera, in metres, rounded to 4 decimals.
            "contacts" (list): The (neck_name, other_body_name) pairs of the chosen pose that are closer than
                cfg["contact_margin"]; empty if collision-free.
            "cost" (float): The cost of the chosen pose.
            "neck_targets" (dict): As `targets`.
            "points" (dict): Per point name a dict with "px" and "py" (pixel position in the image, from the left and from the top),
                "u" and "v" (normalized image coordinates), "depth" (metres along the optical axis), "margin" (fraction of the
                image dimension to the nearest edge), "inside" (bool, margin at least cfg["margin"]) and "outside_by" (how much
                the margin falls short of cfg["margin"], 0 if inside).

    Raises:
        ValueError: If the model has no neck.
    """
    cfg = {**FRAMING_CFG, **cfg}
    if cfg["rule"] == "least_movement":
        cfg = {**cfg, "aim_weight": 0.0, "posture_weight": 0.0, "move_weight": cfg["least_move_weight"]}
    elif cfg["rule"] != "aim_centre":
        raise ValueError("FRAMING_CFG['rule'] is 'aim_centre' or 'least_movement'")
    names, pts = _points_array(points)
    sc = _Scratch(model, data, cfg, neck_specs)
    ids = sc.ids
    lo, hi = ids["lo"], ids["hi"]
    q_now = np.array([data.qpos[a] for a in ids["qadr"]])
    q0 = q_now if start is None else np.asarray(start, float)
    center = 0.5 * (pts.min(axis=0) + pts.max(axis=0))
    f = lambda q: _evaluate(sc, np.clip(q, lo, hi), pts, center, q0)[0]

    cands = []
    if not local:
        grids = [np.linspace(l, h, cfg["coarse_steps"]) for l, h in zip(lo, hi)]
        scored = sorted(((f(np.array(q)), tuple(q)) for q in itertools.product(*grids)), key=lambda t: t[0])
        starts = [np.array(q) for _, q in scored[:cfg["n_refine"]]]
    else:
        starts = [q0]
    for s in starts + ([q0] if not local else []):
        opts = {"maxfev": cfg["refine_evals"], "xatol": 1e-4, "fatol": 1e-8}
        if cfg["simplex_step"]:
            opts["initial_simplex"] = np.vstack([s, s + cfg["simplex_step"] * np.eye(len(s))])
        r = minimize(f, s, method="Nelder-Mead", bounds=list(zip(lo, hi)), options=opts)
        cands.append((float(r.fun), np.clip(r.x, lo, hi)))
    if cfg["rule"] == "least_movement":
        for _, q_ in list(cands):                           # the exact constrained solution next to each simplex result: the optimum sits on the margin, where the penalty search stops imprecisely
            q2 = _polish_least_movement(sc, pts, q0, q_, lo, hi, cfg)
            if q2 is not None:
                cands.append((float(f(q2)), q2))
    cands.sort(key=lambda t: t[0])

    chosen, contacts = None, []
    for cost, q in cands:
        c = sc.contacts(q)
        if not c:
            chosen, contacts = (cost, q), []
            break
        if chosen is None:
            chosen, contacts = (cost, q), c                 # best attempt so far, kept if nothing is clear
    cost, q = chosen
    _, (pos, R, u, v, depth, aim) = _evaluate(sc, q, pts, center, q0)
    W, H = float(sc.res[0]), float(sc.res[1])
    margin = np.minimum((1 - np.abs(u)) / 2, (1 - np.abs(v)) / 2)          # to the nearest edge, fraction of the dimension
    margin = np.where(depth < cfg["near_depth"], -1.0, margin)
    report = {
        "fits": bool(np.all(margin >= cfg["margin"] - 1e-9)), "worst_margin": float(margin.min()), "aim_error_deg": float(np.degrees(aim)),
        "camera_pos": pos.round(4).tolist(), "contacts": contacts, "cost": cost,
        "neck_targets": {n: float(v_) for n, v_ in zip(ids["names"], q)},
        "points": {n: {"px": float((u[i] + 1) / 2 * W), "py": float((1 - v[i]) / 2 * H), "u": float(u[i]), "v": float(v[i]), "depth": float(depth[i]),
                       "margin": float(margin[i]), "inside": bool(margin[i] >= cfg["margin"] - 1e-9),
                       "outside_by": float(max(0.0, cfg["margin"] - margin[i]))} for i, n in enumerate(names)},
    }
    return report["neck_targets"], report


def margins_at(model, data, points, q=None, cfg=FRAMING_CFG, neck_specs=robot_specs.NECK_SPECS):
    """The margin of every point in the camera's image at a neck pose (the current one by default): fractions of the image to the nearest edge, -1 for a point too close to the camera.

    Args:
        model (mujoco.MjModel): The model.
        data (mujoco.MjData): Its data (not modified).
        points (dict or array-like): The world points, as for frame_points.
        q (sequence of float or None): Neck joint angles in radians in the order of the active joints. Defaults to the current ones in `data`.
        cfg (dict): Framing configuration. Defaults to FRAMING_CFG.
        neck_specs (dict): Neck specification. Defaults to robot_specs.NECK_SPECS.

    Returns:
        dict: {point name: margin}.
    """
    cfg = {**FRAMING_CFG, **cfg}
    names, pts = _points_array(points)
    sc = _Scratch(model, data, cfg, neck_specs)
    q = np.array([data.qpos[a] for a in sc.ids["qadr"]]) if q is None else np.asarray(q, float)
    pos, R = sc.pose(q)
    u, v, depth = _project(pts, pos, R, sc.fovy, sc.aspect)
    m = np.where(depth < cfg["near_depth"], -1.0, np.minimum((1 - np.abs(u)) / 2, (1 - np.abs(v)) / 2))
    return {n: float(m[i]) for i, n in enumerate(names)}


def reframe_or_keep(model, data, points, cfg=FRAMING_CFG, neck_specs=robot_specs.NECK_SPECS):
    """The framing at a null step (the base did not move): keep the current neck pose while every point is more than cfg["keep_margin"] (5 %) inside the image, otherwise move the least needed to
    restore the 10 % margin (the least_movement rule from the current pose, whatever FRAMING_CFG["rule"] says).

    Args:
        model (mujoco.MjModel): The model.
        data (mujoco.MjData): Its data: the neck's current pose is the one kept or moved from (not modified).
        points (dict or array-like): The world points, as for frame_points.
        cfg (dict): Framing configuration. Defaults to FRAMING_CFG.
        neck_specs (dict): Neck specification. Defaults to robot_specs.NECK_SPECS.

    Returns:
        tuple: (targets, report, moved). targets: joint name -> radians (the current pose when kept); report: frame_points's report (for a kept pose: "fits", "worst_margin", "camera_pos", "neck_targets", "points"
        margins only); moved (bool).
    """
    cfg = {**FRAMING_CFG, **cfg}
    mg = margins_at(model, data, points, None, cfg, neck_specs)
    sc = _Scratch(model, data, cfg, neck_specs)
    q_now = [float(data.qpos[a]) for a in sc.ids["qadr"]]
    if min(mg.values()) > cfg["keep_margin"]:
        pos, _ = sc.pose(q_now)
        targets = {n: v for n, v in zip(sc.ids["names"], q_now)}
        return targets, {"fits": min(mg.values()) >= cfg["margin"] - 1e-9, "worst_margin": min(mg.values()), "camera_pos": pos.round(4).tolist(), "neck_targets": targets, "points": mg, "contacts": []}, False
    targets, report = frame_points(model, data, points, {**cfg, "rule": "least_movement"}, neck_specs, start=q_now)
    return targets, report, True


def summarize(report):
    """Formats a framing report as one screen of text.

    The first line says whether all points fit, the worst margin, the aim error and the camera position. Then follow, if any, the
    first four neck contacts and the points outside the margin (at most six, the worst first, with their pixel position, margin and
    the margin that was needed), and a count of the further points outside.

    Args:
        report (dict): A report as returned by frame_points.

    Returns:
        str: The text, with lines separated by newlines.
    """
    lines = [f"framing: {'all points inside with the margin' if report['fits'] else 'DOES NOT FIT'}; worst margin {100 * report['worst_margin']:.1f}% "
             f"of the image, aim error {report['aim_error_deg']:.1f} deg, camera at {report['camera_pos']}"]
    if report["contacts"]:
        lines.append(f"  neck contacts: {report['contacts'][:4]}")
    out = sorted(((n, p) for n, p in report["points"].items() if not p["inside"]), key=lambda t: t[1]["margin"])
    for n, p in out[:6]:
        lines.append(f"  outside: {n} at ({p['px']:.0f}, {p['py']:.0f}) px, margin {100 * p['margin']:.1f}% (needs {100 * (p['margin'] + p['outside_by']):.0f}%)")
    if len(out) > 6:
        lines.append(f"  ... and {len(out) - 6} more points outside (worst first above)")
    return "\n".join(lines)


def best_margin(sim, pts):
    """The largest worst-margin any neck pose can give for these points: how much slack the framing really has.

    frame_points() only has to meet the requested 10 % margin and otherwise prefers the pose that aims at the centre of the points and is closest to the posture pose, so its reported margin sits at the limit. This
    searches the neck's joint space (a grid, then Nelder-Mead on the smallest margin) for the pose that maximizes the smallest margin, ignoring neck
    collisions (the result says whether that pose touches anything).

    Args:
        sim (RobotSimulator): The simulator, with the robot placed.
        pts (dict): {name: world point} as framing_points() gives.

    Returns:
        tuple: (best worst-margin as a fraction of the image, name of the point that limits it, True if that neck pose is collision-free).
    """
    m, d = sim.model, sim.data
    names = list(pts)
    P = np.array([pts[n] for n in names], float)
    sc = _Scratch(m, d, dict(FRAMING_CFG), robot_specs.NECK_SPECS)
    lo, hi = sc.ids["lo"], sc.ids["hi"]

    def margins(q):
        pos, R = sc.pose(np.clip(q, lo, hi))
        u, v, depth = _project(P, pos, R, sc.fovy, sc.aspect)
        return np.where(depth < FRAMING_CFG["near_depth"], -1.0, np.minimum((1 - np.abs(u)) / 2, (1 - np.abs(v)) / 2))

    grids = [np.linspace(a, b, 9) for a, b in zip(lo, hi)]
    scored = sorted(((-margins(np.array(q)).min(), tuple(q)) for q in itertools.product(*grids)))
    best = None
    for _, q in scored[:8]:
        r = minimize(lambda x: -margins(x).min(), np.array(q), method="Nelder-Mead", options={"maxfev": 400, "xatol": 1e-5, "fatol": 1e-9})
        if best is None or r.fun < best[0]:
            best = (r.fun, np.clip(r.x, lo, hi))
    mg = margins(best[1])
    return float(mg.min()), names[int(mg.argmin())], not sc.contacts(best[1])
